const cfg = $('Collector Config').first().json;
const pages = $input.all();
const seen = new Set();
const posts = [];
const authors = new Map();

for (const item of pages) {
  const page = item.json ?? {};
  for (const user of (page.includes?.users ?? [])) {
    authors.set(String(user.id), user);
  }
  for (const post of (page.data ?? [])) {
    const id = String(post.id ?? '');
    if (!id || seen.has(id)) continue;
    seen.add(id);
    posts.push(post);
    if (posts.length >= 1000) break;
  }
  if (posts.length >= 1000) break;
}

const sources = posts.map(post => {
  const author = authors.get(String(post.author_id ?? '')) ?? {};
  const refs = Array.isArray(post.referenced_tweets) ? post.referenced_tweets : [];
  const isBareRetweet = refs.some(r => r.type === 'retweeted') && /^RT\s+@/i.test(post.text ?? '');
  const isReply = refs.some(r => r.type === 'replied_to');
  const isQuote = refs.some(r => r.type === 'quoted');
  return {
    season_code: cfg.season_code,
    week_number: Number(cfg.week_number),
    provider: 'x',
    source_type: 'curated_post',
    external_id: String(post.id),
    canonical_url: author.username ? `https://x.com/${author.username}/status/${post.id}` : null,
    author_name: author.name || author.username || null,
    body_text: String(post.text ?? ''),
    published_at: post.created_at || null,
    metadata: {
      x_author_id: post.author_id || null,
      x_username: author.username || null,
      conversation_id: post.conversation_id || null,
      referenced_tweets: refs,
      public_metrics: post.public_metrics || {},
      entities: post.entities || {},
      bare_retweet: isBareRetweet,
      reply: isReply,
      quote_post: isQuote
    }
  };
});

return [{
  json: {
    sources,
    collected_count: sources.length,
    hit_ceiling: sources.length >= 1000,
    mode: 'live'
  }
}];

